messages.content:
Here's the new File Explorer, built from scratch with a GitHub-like browse → view → edit flow.

### 1. New component

```vue client/src/components/filebrowser/FileExplorer.vue
<script setup>
import moment from 'moment'
import hljs from 'highlight.js'
import { VueCodeHighlighter } from 'vue-code-highlighter'
import 'vue-code-highlighter/dist/style.css'
import Editor from '../monaco/Editor.vue'
import { EXTENSION_LANGUAGE_MAP } from '../../store'
</script>

<template>
  <div class="w-full h-full flex flex-col gap-2 p-2 overflow-hidden">
    <!-- Toolbar: breadcrumb + actions -->
    <div class="flex items-center gap-2">
      <div class="breadcrumbs text-sm py-0 flex-1 overflow-x-auto">
        <ul>
          <li>
            <a class="gap-1" @click="goToRoot">
              <i class="fa-solid fa-house text-xs"></i>
              {{ projectName }}
            </a>
          </li>
          <li v-for="(part, ix) in breadcrumbParts" :key="ix">
            <a v-if="ix < breadcrumbParts.length - 1 || openedFile" @click="goToPart(ix)">
              {{ part }}
            </a>
            <span class="font-semibold" v-else>{{ part }}</span>
          </li>
          <li v-if="openedFile">
            <span class="font-semibold">{{ openedFile.name }}</span>
          </li>
        </ul>
      </div>

      <div class="input input-sm input-bordered flex items-center gap-2 w-56" v-if="!openedFile">
        <i class="fa-solid fa-filter opacity-60"></i>
        <input
          type="text"
          v-model="filter"
          placeholder="Filter..."
          class="grow bg-transparent outline-none text-sm"
        />
        <span class="cursor-pointer" @click="filter = ''" v-if="filter">
          <i class="fa-regular fa-circle-xmark"></i>
        </span>
      </div>

      <button class="btn btn-sm btn-ghost" title="Refresh" @click="refresh">
        <i class="fa-solid fa-arrows-rotate" :class="loading && 'animate-spin'"></i>
      </button>
    </div>

    <!-- Error banner -->
    <div class="alert alert-error py-2" v-if="error">
      <i class="fa-solid fa-triangle-exclamation"></i>
      <span class="text-sm">{{ error }}</span>
    </div>

    <!-- Directory listing -->
    <div class="grow overflow-auto border border-base-300 rounded-lg" v-if="!openedFile">
      <div class="flex items-center justify-center h-32" v-if="loading">
        <span class="loading loading-spinner loading-md"></span>
      </div>
      <div class="flex flex-col divide-y divide-base-300" v-else>
        <!-- Parent folder row -->
        <div
          class="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-base-200"
          @click="goUp"
          v-if="currentPath !== '.'"
        >
          <i class="fa-solid fa-folder text-warning w-4"></i>
          <span class="text-sm font-mono">..</span>
        </div>

        <!-- Entries -->
        <div
          v-for="entry in visibleEntries"
          :key="entry.file_path"
          class="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-base-200"
          @click="openEntry(entry)"
        >
          <i
            class="w-4 text-sm"
            :class="entry.is_dir ? 'fa-solid fa-folder text-warning' : 'fa-regular fa-file text-info'"
          ></i>
          <span class="text-sm font-mono flex-1 truncate" :title="entry.name">{{ entry.name }}</span>
          <span class="text-xs opacity-50 w-20 text-right" v-if="!entry.is_dir">
            {{ formatSize(entry.size) }}
          </span>
          <span class="text-xs opacity-50 w-32 text-right hidden sm:block">
            {{ entry.last_modification ? moment(entry.last_modification).fromNow() : '' }}
          </span>
        </div>

        <div class="text-center opacity-50 py-8 text-sm" v-if="!visibleEntries.length">
          No files found
        </div>
      </div>
    </div>

    <!-- File view / edit -->
    <div class="grow flex flex-col overflow-hidden border border-base-300 rounded-lg" v-else>
      <!-- File header -->
      <div class="flex items-center gap-3 px-3 py-2 bg-base-200 border-b border-base-300">
        <i class="fa-regular fa-file text-info"></i>
        <span class="text-sm font-mono font-semibold truncate" :title="openedFile.path">
          {{ openedFile.name }}
        </span>
        <span class="text-xs opacity-50" v-if="fileMeta.size !== null">
          {{ formatSize(fileMeta.size) }}
        </span>
        <span class="text-xs opacity-50" v-if="fileMeta.last_modification">
          {{ moment(fileMeta.last_modification).fromNow() }}
        </span>
        <div class="grow"></div>

        <button class="btn btn-xs btn-ghost" title="Copy content" @click="copyContent" v-if="!editMode">
          <i class="fa-solid fa-copy"></i>
        </button>
        <button class="btn btn-xs btn-outline" @click="startEdit" v-if="!editMode && !isBinary">
          <i class="fa-solid fa-pen"></i> Edit
        </button>
        <template v-if="editMode">
          <button class="btn btn-xs btn-ghost" @click="cancelEdit">
            <i class="fa-solid fa-xmark"></i> Cancel
          </button>
          <button class="btn btn-xs btn-success" :disabled="saving" @click="saveFile">
            <span class="loading loading-spinner loading-xs" v-if="saving"></span>
            <i class="fa-solid fa-floppy-disk" v-else></i> Save
          </button>
        </template>
        <button class="btn btn-xs btn-ghost" title="Close file" @click="closeFile">
          <i class="fa-solid fa-rectangle-xmark"></i>
        </button>
      </div>

      <!-- File content -->
      <div class="grow overflow-auto">
        <div class="flex items-center justify-center h-32" v-if="loading">
          <span class="loading loading-spinner loading-md"></span>
        </div>
        <Editor
          v-model="editContent"
          :fileName="openedFile.path"
          class="h-full"
          v-else-if="editMode"
        />
        <div class="flex items-center justify-center h-32 opacity-50 text-sm" v-else-if="isBinary">
          <i class="fa-regular fa-image mr-2"></i> Preview not available for this file type
        </div>
        <VueCodeHighlighter
          class="h-full"
          :code="fileContent"
          :lang="validatedLanguage"
          :title="openedFile.name"
          v-else-if="fileContent"
        />
        <div class="flex items-center justify-center h-32 opacity-50 text-sm" v-else>
          Empty file
        </div>
      </div>
    </div>
  </div>
</template>

<script>
const BINARY_EXTENSIONS = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'ico', 'pdf', 'zip', 'tar', 'gz', 'woff', 'woff2', 'ttf', 'eot']

export default {
  data() {
    return {
      currentPath: '.',
      entries: [],
      filter: '',
      loading: false,
      error: null,
      openedFile: null,
      fileContent: '',
      fileMeta: { size: null, last_modification: null },
      editMode: false,
      editContent: '',
      saving: false
    }
  },
  computed: {
    $api() {
      return this.$storex.api
    },
    projectName() {
      return this.$storex.projects.activeProject?.project_name || 'root'
    },
    projectId() {
      return this.$storex.projects.activeProject?.project_id
    },
    breadcrumbParts() {
      return this.currentPath === '.' ? [] : this.currentPath.split('/')
    },
    // Folders first, alphabetical, filtered
    visibleEntries() {
      const filter = this.filter.toLowerCase()
      return this.entries
        .filter(e => e.name?.trim())
        .filter(e => !filter || e.name.toLowerCase().includes(filter))
        .sort((a, b) => {
          if (a.is_dir !== b.is_dir) return a.is_dir ? -1 : 1
          return a.name.localeCompare(b.name)
        })
    },
    fileExtension() {
      return this.openedFile?.name.split('.').pop()?.toLowerCase()
    },
    isBinary() {
      return BINARY_EXTENSIONS.includes(this.fileExtension)
    },
    validatedLanguage() {
      const lang = EXTENSION_LANGUAGE_MAP[this.fileExtension] || this.fileExtension
      try {
        if (lang && hljs.getLanguage(lang)) return lang
      } catch (ex) {
        console.warn(`Invalid language detected: ${lang}`, ex)
      }
      return 'markdown'
    }
  },
  watch: {
    // Reset explorer when active project changes
    projectId() {
      this.closeFile()
      this.loadDir('.')
    }
  },
  mounted() {
    this.loadDir('.')
  },
  methods: {
    async loadDir(path) {
      this.loading = true
      this.error = null
      try {
        const { files } = await this.$api.files.list(path)
        this.currentPath = path
        this.entries = files || []
        this.filter = ''
      } catch (ex) {
        console.error('Error listing files', ex)
        this.error = `Error listing "${path}"`
      } finally {
        this.loading = false
      }
    },
    entryPath(entry) {
      return this.currentPath === '.' ? entry.name : `${this.currentPath}/${entry.name}`
    },
    openEntry(entry) {
      const path = this.entryPath(entry)
      if (entry.is_dir) {
        this.loadDir(path)
      } else {
        this.openFile(path, entry.name)
      }
    },
    async openFile(path, name) {
      this.loading = true
      this.error = null
      this.openedFile = { path, name }
      this.editMode = false
      try {
        const { content, last_modification, size } = await this.$api.files.read(path)
        this.fileContent = content
        this.fileMeta = { last_modification, size }
      } catch (ex) {
        console.error('Error reading file', ex)
        this.error = `Error reading "${path}"`
        this.openedFile = null
      } finally {
        this.loading = false
      }
    },
    closeFile() {
      this.openedFile = null
      this.fileContent = ''
      this.fileMeta = { size: null, last_modification: null }
      this.editMode = false
      this.editContent = ''
    },
    goToRoot() {
      this.closeFile()
      this.loadDir('.')
    },
    goToPart(ix) {
      this.closeFile()
      this.loadDir(this.breadcrumbParts.slice(0, ix + 1).join('/'))
    },
    goUp() {
      const parts = this.breadcrumbParts.slice(0, -1)
      this.loadDir(parts.length ? parts.join('/') : '.')
    },
    refresh() {
      if (this.openedFile) {
        this.openFile(this.openedFile.path, this.openedFile.name)
      } else {
        this.loadDir(this.currentPath)
      }
    },
    startEdit() {
      this.editContent = this.fileContent
      this.editMode = true
    },
    cancelEdit() {
      this.editMode = false
      this.editContent = ''
    },
    async saveFile() {
      this.saving = true
      try {
        await this.$api.files.write(this.openedFile.path, this.editContent)
        this.fileContent = this.editContent
        this.editMode = false
        this.$ui.addNotification({ text: `${this.openedFile.name} saved` })
        // Refresh metadata after save
        const { last_modification, size } = await this.$api.files.read(this.openedFile.path)
        this.fileMeta = { last_modification, size }
      } catch (ex) {
        console.error('Error saving file', ex)
        this.error = `Error saving "${this.openedFile.path}"`
      } finally {
        this.saving = false
      }
    },
    copyContent() {
      this.$ui.copyTextToClipboard(this.fileContent)
    },
    formatSize(size) {
      if (size === null || size === undefined) return ''
      return size > 1024 ? `${Math.round(size / 1024)} KB` : `${size} B`
    }
  }
}
</script>
```

### 2. Register it in `Desktop.vue` (replacing FileFinder)

Change the import:

```vue client/src/components/desktop/Desktop.vue
import FileExplorerVue from '../filebrowser/FileExplorer.vue'
```

And the component registration (the `'file-finder'` key stays, so the existing "File explorer" menu entry keeps working with no menu changes):

```vue client/src/components/desktop/Desktop.vue
    'file-finder': FileExplorerVue,
```

### 3. Remove the old component

Delete the file:

```bash
rm client/src/components/filebrowser/FileFinder.vue
```

### Summary

- **Browse**: GitHub-style directory listing (folders first, `..` row, size + relative modification date, quick filter), breadcrumb navigation with project name as root.
- **View**: syntax-highlighted read-only view via `VueCodeHighlighter`, with copy button; binary extensions show a "preview not available" note.
- **Edit**: `Edit` toggles the Monaco editor, `Save` persists via `API.files.write` and refreshes metadata, `Cancel` discards.
- Resets to root automatically when the active project changes.
